'use strict';
const covers={"photo": "assets/images/curated-20261011/photo-05.webp", "lan": "assets/images/curated-20261011/lan-03.webp", "song": "assets/images/curated-20261011/song-05.webp"};
const projects={
photo:{title:'第十张照片',en:'THE TENTH PHOTOGRAPH',category:'AI 青春叙事短片',duration:'01:20',format:'16:9 · 网页观看版',synopsis:'一个不愿面对镜头的女孩，一本留下最后空白页的相册。通过校园日常、自然笑容与毕业合照，把人物关系组织成完整短片。',notes:[['叙事与视听','从躲镜头到自然笑容，再到共同完成合照。配合走廊、公交站与空教室，形成情绪推进。'],['角色素材','人物正面、左右45度、表情及同框比例参考，为多场景生成提供固定依据。'],['镜头迭代','针对人物外貌、视线、手部、相机道具与画面清晰度，调整参考图和镜头提示词。']]},
lan:{title:'岚翁和小角兽',en:'LAN & THE LITTLE HORNED BEAST',category:'AI 二维手绘动画',duration:'00:50',format:'横屏 · 网页观看版',synopsis:'兔形老人和小角兽穿过林间与田野。从拘谨的跟随，到雨中逐渐靠近，用动作与环境变化呈现温暖的陪伴。',notes:[['角色与美术风格','以角色设定、风格与体型参考为基础，保持斗笠、服装、角与背鳍等识别特征。'],['参考图分工','将身份、风格、环境及白模构图分别约束，避免构图参考改变二维手绘质感。'],['动作与镜头','提示词具体描述步伐、前后距离、真实位移和跟拍速度，区分人物前进与单纯背景移动。']]},
song:{title:'草木入色',en:'COLOUR FROM NATURE',category:'宋式美学系列',duration:'00:23',format:'16:9 · 网页观看版',synopsis:'围绕水边洗布、搅染、展布与人物生活动作展开。用素色衣料、自然光和江南水岸，探索克制的东方生活美学。',notes:[['视觉方向','围绕自然肤色、朴素衣料、木质容器和水岸环境，探索画面整体的材质与色彩。'],['系列素材','以人物、服饰、场景与多个生活镜头的生成图，构成同一主题下的视觉探索。'],['成片观察','以水、布料、手部动作和人物姿态连接镜头，呈现生活过程与画面氛围。']]},
};
for(const slug of ['photo','lan','song'])projects[slug].notes.unshift(['本人负责','使用Midjourney生成图像、Seedance 2.0与小云雀制作视频，使用剪映完成成片剪辑和基础音乐剪辑；通过Codex调用AI Agent辅助分镜、提示词与素材制作。']);
let galleryItems=[],filteredImages=[],currentImageIndex=0,currentFilm='photo',lastFilmFocus=null,lastImageFocus=null;
const processImages=[{"id": "campus", "project": "photo", "title": "校园走廊场景", "kind": "制作过程参考素材", "src": "assets/images/curated-20261011/photo-04.webp"}, {"id": "girl", "project": "photo", "title": "女主角色与服装参考", "kind": "制作过程参考素材", "src": "assets/images/curated-20261011/photo-01.webp"}, {"id": "boy", "project": "photo", "title": "男主角色与服装参考", "kind": "制作过程参考素材", "src": "assets/images/curated-20261011/photo-02.webp"}, {"id": "vending", "project": "photo", "title": "相机正面道具参考", "kind": "制作过程参考素材", "src": "assets/images/curated-20261011/photo-08.webp"}, {"id": "studio", "project": "photo", "title": "相机背面细节参考", "kind": "制作过程参考素材", "src": "assets/images/curated-20261011/photo-09.webp"}, {"id": "corridor", "project": "photo", "title": "走廊人物镜头参考", "kind": "制作过程参考素材", "src": "assets/images/curated-20261011/photo-05.webp"}];
const filmDialog=document.querySelector('#film-dialog'),imageDialog=document.querySelector('#image-dialog'),player=document.querySelector('#film-player'),hero=document.querySelector('#hero-video');
const escapeHtml=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function openFilm(slug){const film=projects[slug];if(!film)return;currentFilm=slug;if(!filmDialog.open)lastFilmFocus=document.activeElement;document.querySelector('#dialog-film-title').textContent=film.title;document.querySelector('#dialog-category').textContent=film.category;document.querySelector('#dialog-en-title').textContent=film.en;document.querySelector('#dialog-synopsis').textContent=film.synopsis;document.querySelector('#project-meta').innerHTML=`<span>2026 · 个人创作</span><span>${film.duration}</span><span>${film.format}</span>`;document.querySelector('#project-notes').innerHTML=film.notes.map(([title,body])=>`<p><strong>${escapeHtml(title)}</strong>${escapeHtml(body)}</p>`).join('');document.querySelector('#project-gallery').innerHTML=galleryItems.filter(x=>x.project===slug).map(x=>`<button data-image="${x.id}" aria-label="放大${escapeHtml(x.title)}"><img src="${x.src}" alt="${escapeHtml(x.title)}" loading="lazy"><p>${escapeHtml(x.title)}</p></button>`).join('');player.pause();player.poster=covers[slug];player.src=`assets/video/${slug}.mp4`;document.querySelector('.screening').classList.remove('portrait');document.querySelector('#play-status').textContent='';const slugs=Object.keys(projects),next=slugs[(slugs.indexOf(slug)+1)%slugs.length];const btn=document.querySelector('#next-film-button');btn.dataset.next=next;btn.innerHTML=`${escapeHtml(projects[next].title)} <span>↗</span>`;if(!filmDialog.open)filmDialog.showModal();filmDialog.scrollTop=0;document.body.classList.add('modal-open');hero.pause();player.play().catch(()=>{});}
function closeFilm(){player.pause();player.removeAttribute('src');player.load();filmDialog.close();document.body.classList.remove('modal-open');if(!document.querySelector('#motion-toggle').dataset.paused&&!window.matchMedia('(prefers-reduced-motion: reduce)').matches)hero.play().catch(()=>{});if(lastFilmFocus)lastFilmFocus.focus();}
function renderGallery(filter='all'){filteredImages=filter==='all'?galleryItems:galleryItems.filter(x=>x.project===filter);document.querySelector('#gallery').innerHTML=filteredImages.map(x=>`<button class="gallery-item" data-image="${x.id}" aria-label="放大${escapeHtml(x.title)}"><img src="${x.src}" alt="${escapeHtml(x.title)}" loading="lazy" width="${x.width}" height="${x.height}"><p>${escapeHtml(x.title)}<span>${escapeHtml(x.kind)}</span></p></button>`).join('');document.querySelector('#gallery-count').textContent=`${filteredImages.length} IMAGES`;}
function showImage(id){let selected=galleryItems.find(x=>x.id===Number(id));if(!selected)return;if(!filteredImages.some(x=>x.id===selected.id))filteredImages=galleryItems.filter(x=>x.project===selected.project);currentImageIndex=filteredImages.findIndex(x=>x.id===selected.id);updateImage();if(!imageDialog.open){lastImageFocus=document.activeElement;imageDialog.showModal();}document.body.classList.add('modal-open');}
function updateImage(){const item=filteredImages[currentImageIndex];if(!item)return;document.querySelector('#large-image').src=item.src;document.querySelector('#large-image').alt=item.title;document.querySelector('#image-title').textContent=`${projects[item.project].title} / ${item.title} / ${item.kind}`;document.querySelector('#image-position').textContent=`${currentImageIndex+1} / ${filteredImages.length}`;}
function stepImage(step){currentImageIndex=(currentImageIndex+step+filteredImages.length)%filteredImages.length;updateImage();}
function showProcessImage(id){const selected=processImages.find(x=>x.id===id);if(!selected)return;filteredImages=processImages;currentImageIndex=filteredImages.indexOf(selected);updateImage();if(!imageDialog.open){lastImageFocus=document.activeElement;imageDialog.showModal();}document.body.classList.add('modal-open');}
function closeImage(){imageDialog.close();if(!filmDialog.open)document.body.classList.remove('modal-open');if(lastImageFocus)lastImageFocus.focus();}
document.addEventListener('click',e=>{const film=e.target.closest('[data-film]');if(film){openFilm(film.dataset.film);return;}const image=e.target.closest('[data-image]');if(image){showImage(image.dataset.image);return;}const filter=e.target.closest('[data-filter]');if(filter){document.querySelectorAll('[data-filter]').forEach(b=>{const active=b===filter;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active));});renderGallery(filter.dataset.filter);}});
document.querySelector('#close-film').addEventListener('click',closeFilm);document.querySelector('#close-image').addEventListener('click',closeImage);document.querySelector('#next-film-button').addEventListener('click',e=>openFilm(e.currentTarget.dataset.next));document.querySelector('#previous-image').addEventListener('click',()=>stepImage(-1));document.querySelector('#next-image').addEventListener('click',()=>stepImage(1));filmDialog.addEventListener('cancel',e=>{e.preventDefault();closeFilm();});imageDialog.addEventListener('cancel',e=>{e.preventDefault();closeImage();});document.addEventListener('keydown',e=>{if(imageDialog.open){if(e.key==='ArrowRight')stepImage(1);if(e.key==='ArrowLeft')stepImage(-1);}});for(const dialog of [filmDialog,imageDialog])dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom){dialog===filmDialog?closeFilm():closeImage();}}});
document.querySelector('#motion-toggle').addEventListener('click',e=>{const b=e.currentTarget;if(hero.paused){hero.play().catch(()=>{});delete b.dataset.paused;b.innerHTML='Ⅱ <span>选段预览</span>';b.setAttribute('aria-label','暂停背景预览');}else{hero.pause();b.dataset.paused='true';b.innerHTML='▶ <span>选段预览</span>';b.setAttribute('aria-label','播放背景预览');}});player.addEventListener('error',()=>{document.querySelector('#play-status').textContent='视频暂时未能加载，请关闭后重试。';});document.addEventListener('visibilitychange',()=>{if(document.hidden){hero.pause();player.pause();}else if(!filmDialog.open&&!document.querySelector('#motion-toggle').dataset.paused&&!window.matchMedia('(prefers-reduced-motion: reduce)').matches)hero.play().catch(()=>{});});
const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target);}}),{threshold:.12});document.querySelectorAll('.reveal').forEach(e=>{e.classList.add('js-reveal');observer.observe(e);});if(window.matchMedia('(prefers-reduced-motion: reduce)').matches){hero.pause();document.querySelector('#motion-toggle').dataset.paused='true';document.querySelector('#motion-toggle').innerHTML='▶ <span>选段预览</span>';}
fetch('gallery-curated-20261011.json').then(r=>{if(!r.ok)throw new Error('gallery unavailable');return r.json();}).then(items=>{galleryItems=items;renderGallery();if(location.hash==='#process')document.querySelector('#process').scrollIntoView({behavior:'instant',block:'start'});}).catch(()=>{document.querySelector('#gallery').innerHTML='<p>图片素材暂未加载，请刷新页面重试。</p>';});
document.addEventListener('click',e=>{const image=e.target.closest('[data-process-image]');if(image)showProcessImage(image.dataset.processImage);});
const filmProcessLink=document.querySelector('#film-process-link');
filmProcessLink.addEventListener('click',()=>{closeFilm();});
filmDialog.addEventListener('close',()=>{filmProcessLink.hidden=true;});
document.addEventListener('click',e=>{const film=e.target.closest('[data-film]');if(film)filmProcessLink.hidden=film.dataset.film!=='photo';const next=e.target.closest('#next-film-button');if(next)filmProcessLink.hidden=currentFilm!=='photo';});
